                "operationId": "create-account-user",
                "summary": "Create Account User",
                "description": "Adds a user to the target account.\n\nIf no user with the given email or username exists, a new user is created and sent a welcome email containing a generated password. If a matching user already exists, that user is added to the account instead.",
                "method": "POST",
                "path": "/v1/identity/account-users",
                "domain": "identity",
                "tag": "Account Users Management",
                "tagSlug": "account-users-management",
                "endpointSlug": "create-account-user",
                "actionType": "create",
