                "operationId": "activate-account-user",
                "summary": "Activate Account User",
                "description": "Activates a disabled or removed account user, restoring their access to the target account.\n\nReactivation consumes a seat, so the request fails if the account is at its seat limit. Activating an already-active user is a no-op.",
                "method": "PUT",
                "path": "/v1/identity/account-users/{id}/actions/activate",
                "domain": "identity",
                "tag": "Account Users Management",
                "tagSlug": "account-users-management",
                "endpointSlug": "activate-account-user",
                "actionType": "action",
