                "operationId": "add-item-attribute",
                "summary": "Add Item Attribute",
                "description": "Adds an attribute to an item and returns the updated item.\n\nIf the attribute is already associated with the item, this is a no-op.",
                "method": "PUT",
                "path": "/v1/catalog/items/{id}/attributes/{attribute_id}",
                "domain": "catalog",
                "tag": "Items Management",
