                "operationId": "delete-customer",
                "summary": "Delete Customer",
                "description": "Deletes a customer.\n\nFails with a conflict error if any sales orders still reference the customer; delete or reassign those orders, or merge the customer into another first.",
                "method": "DELETE",
                "path": "/v1/sales/customers/{id}",
                "domain": "sales",
                "tag": "Customers",
                "tagSlug": "customers",
                "endpointSlug": "delete-customer",
                "actionType": "delete",
